from __future__ import annotations

from dataclasses import dataclass, field


@dataclass(frozen=True)
class VisionRegressionExpectation:
    activity: str = ""
    summary: str | None = None
    display_title: str | None = None
    scenario: str | None = None
    signal_type: str | None = None
    expect_payload: bool | None = None
    record_care_event: bool | None = None
    session_bucket: str | None = None
    session_risk: str | None = None
    is_reliable: bool | None = None
    description_contains: tuple[str, ...] = ()
    description_excludes: tuple[str, ...] = ()
    forbidden_display_titles: tuple[str, ...] = ()


@dataclass(frozen=True)
class VisionRegressionCase:
    case_id: str
    title: str
    raw_model: dict
    expect: VisionRegressionExpectation
    notes: str = ""
    use_validator: bool = True
    confidence: float = 0.86
    tags: tuple[str, ...] = field(default_factory=tuple)


